/* setComplaint */
INSERT INTO TH_CMPLNT (
            USER_NUMB
          , TAGT_TYPE
          , TAGT_NUMB
          , TAGT_USER
          , TAGT_CNTN
          , CMPL_RSON
          , CMPL_CNTN
          , CMPL_STAT
) VALUES (  #{userNumb}
          , #{complaint.tagtType}
          , #{complaint.tagtNumb}
          , #{complaint.tagtUser}
          , #{complaint.tagtCntn,jdbcType=LONGVARCHAR}
          , #{complaint.cmplRson}
          , #{complaint.cmplCntn,jdbcType=VARCHAR}
          , #{complaintStatusReceived}
)

mapper.select:

SELECT /* getAutoActionCmplCnt */
       COUNT(1)
  FROM TH_CMPLNT
 WHERE TAGT_TYPE = #{tagtType}
   AND TAGT_NUMB = #{tagtNumb}
   AND CMPL_STAT != #{complaintStatusRejected}
   FOR UPDATE

mapper.delete:

DELETE /* delAutoReplLike */ L
  FROM TB_LIKEXX L
  JOIN TB_REPLXX R
    ON R.REPL_NUMB = L.TAGT_NUMB
   AND R.REPT_NUMB = #{tagtNumb}
 WHERE L.TAGT_TYPE = #{likeTargetReply}

DELETE /* delAutoReplyList */
  FROM TB_REPLXX
 WHERE REPT_NUMB = #{tagtNumb}


DELETE /* delAutoReportLike */
  FROM TB_LIKEXX
 WHERE TAGT_TYPE = #{likeTargetReport}
   AND TAGT_NUMB = #{tagtNumb}

DELETE /* delAutoReport */
  FROM TM_REPORT
 WHERE REPT_NUMB = #{tagtNumb}
   AND USER_NUMB = #{tagtUser}

mapper.update:

UPDATE /* delAutoReply */
       TB_REPLXX
   SET DELT_YSNO = #{commYes}
     , UPDT_DATE = CURRENT_TIMESTAMP
 WHERE REPL_NUMB = #{tagtNumb}
   AND USER_NUMB = #{tagtUser}
   AND COALESCE(DELT_YSNO, #{commNo}) = #{commNo}

mapper.insert:
/* setAutoAction */
INSERT INTO TH_CMACTN (
            TAGT_TYPE
          , TAGT_NUMB
          , TAGT_USER
          , ACTN_TYPE
          , RSLT_CODE
          , THRS_CNTT
          , CMPL_CNTT
          , ACTN_ORDR
          , TRIG_CMPL
          , RSLT_CNTN
) VALUES (  #{tagtType}
          , #{tagtNumb}
          , #{tagtUser,jdbcType=NUMERIC}
          , #{actnType}
          , #{rsltCode}
          , #{thrsCntt}
          , #{cmplCntt}
          , #{actnOrdr}
          , #{trigCmpl,jdbcType=NUMERIC}
          , #{rsltCntn,jdbcType=VARCHAR}
)

mapper.update:

UPDATE /* uptAutoComplaints */
       TH_CMPLNT
   SET CMPL_STAT = #{complaintStatusActioned}
     , PROC_CNTN = #{procCntn}
     , PROC_ADMN = NULL
     , PROC_DATE = CURRENT_TIMESTAMP
     , UPDT_DATE = CURRENT_TIMESTAMP
 WHERE TAGT_TYPE = #{tagtType}
   AND TAGT_NUMB = #{tagtNumb}
   AND CMPL_STAT IN (#{complaintStatusReceived}, #{complaintStatusReviewing})
